def regionsBySlashes(grid: list[str]) -> int:
    n = len(grid)
    size = 3 * n
    matrix = [[0] * size for _ in range(size)]
    for r in range(n):
        for c in range(n):
            ch = grid[r][c]
            if ch == '/':
                matrix[r * 3][c * 3 + 2] = 1
                matrix[r * 3 + 1][c * 3 + 1] = 1
                matrix[r * 3 + 2][c * 3] = 1
            elif ch == chr(92):
                matrix[r * 3][c * 3] = 1
                matrix[r * 3 + 1][c * 3 + 1] = 1
                matrix[r * 3 + 2][c * 3 + 2] = 1
    def dfs(r, c):
        if 0 <= r < size and 0 <= c < size and matrix[r][c] == 0:
            matrix[r][c] = 1
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)
    regions = 0
    for r in range(size):
        for c in range(size):
            if matrix[r][c] == 0:
                regions += 1
                dfs(r, c)
    return regions

